import {typography} from './type-scale.mjs';
// A layered photographic scene retains its photograph and original overlay pairs.
// Foreground pixels are never cropped, reconstructed or treated as a clean background.
export function photoSceneCandidates(graph,elements,{width,height}){
 if(graph.catalog?.mode!=='photo-scene'||graph.manual||graph.locked)return{plans:[],failures:[]};
 const plans=[];for(let variant=0;variant<3;variant++){
  const S=Math.min(width,height),m=S*.05,gap=S*.016,wide=width/height>=1.4,photo=graph.nodes.find(n=>n.id===graph.catalog.cards[0].photos[0]),b=photo.source,available=wide?{x:width*.35,y:m,w:width*.65-m,h:height-m*2}:{x:m,y:height*.20,w:width-m*2,h:height*.75},scale=Math.min(available.w/b.w,available.h/b.h),frame={x:available.x+(available.w-b.w*scale)/2,y:available.y,w:b.w*scale,h:b.h*scale},placements=[],used=new Set(),groups={},floors={},minimums={},roles=Object.fromEntries(graph.nodes.map(n=>[n.id,n.role])),factor=[1,.96,.91][variant];
  const put=(n,cell,role=n.role)=>{const t=typography(n.catalogRole||role,S),key='scene:'+n.id,round=graph.nodes.some(b=>b.materialAttachTo===n.id&&b.source.w/b.source.h>.8&&b.source.w/b.source.h<1.2);if(round){const size=Math.min(S*.14,cell.w,cell.h);cell={...cell,w:size,h:size};}placements.push({id:n.id,role:n.role,groupRole:n.role,layoutGroup:key,...cell,zone:cell,scale:1,readableBody:true,readableSize:t.target*factor,minimumSize:t.minimum,align:round?'center':'left',verticalAlign:'center',keepRowAnchors:true});used.add(n.id);groups[n.id]=key;floors[n.id]=t.minimum;minimums[n.id]=t;};
  placements.push({id:photo.id,role:'subject',groupRole:'subject',layoutGroup:'scene-photo',x:frame.x,y:frame.y,w:frame.w,h:frame.h,scale:scale*b.w/photo.w});used.add(photo.id);groups[photo.id]='scene-photo';
  const native=graph.nodes.filter(n=>n.kind==='text'),titles=native.filter(n=>n.role==='title'),small=native.filter(n=>n.originalFont<Math.max(...titles.map(t=>t.originalFont))*.09&&n.source.y<b.y),info=native.filter(n=>n.information.length&&n.source.y>b.y+b.h*.65),remaining=native.filter(n=>!titles.includes(n)&&!small.includes(n)&&!info.includes(n));
  for(const [i,n]of small.sort((a,b)=>a.source.x-b.source.x).entries())put(n,{x:m+i*(width-m*2)/small.length,y:m,w:(width-m*2)/small.length-gap,h:S*.045},'logo');
  for(const n of titles)put(n,wide?{x:m,y:height*.13,w:width*.42,h:height*.35}:{x:m,y:height*.07,w:width-m*2,h:height*.24},'title');
  for(const n of remaining){const rx=(n.source.x-b.x)/b.w,ry=(n.source.y-b.y)/b.h;put(n,{x:frame.x+Math.max(0,Math.min(.78,rx))*frame.w,y:frame.y+Math.max(.06,Math.min(.65,ry))*frame.h,w:Math.min(width-m-(frame.x+Math.max(0,Math.min(.78,rx))*frame.w),Math.max(frame.w*.24,n.source.w/b.w*frame.w)),h:Math.max(S*.14,n.source.h/b.h*frame.h*1.5)});}
  for(const n of info)put(n,{x:m+gap,y:frame.y+frame.h*.84,w:width-m*2-gap*2,h:Math.min(height-m-(frame.y+frame.h*.84),S*.14)},'details');
  for(const n of graph.nodes.filter(n=>n.kind!=='text'&&n.role!=='background'&&!used.has(n.id))){const target=n.materialAttachTo!==undefined?placements.find(p=>p.id===n.materialAttachTo):null;if(!target)continue;
   const native=graph.nodes.find(x=>x.id===n.materialAttachTo),relative=(n.source.w*n.source.h)/(native.source.w*native.source.h),cell=target.zone;
   if(n.source.w/n.source.h>3){placements.push({id:n.id,role:n.role,groupRole:n.role,layoutGroup:groups[native.id],x:Math.max(0,cell.x-gap),y:cell.y-gap/2,w:Math.min(width,cell.w+gap*2),h:cell.h+gap,scale:1,stretchDecoration:true,decorationThickness:cell.h+gap,angle:0});}
   else{const sc=Math.min(cell.w/n.w,cell.h/n.h);placements.push({id:n.id,role:n.role,groupRole:n.role,layoutGroup:groups[native.id],x:cell.x,y:cell.y,w:n.w*sc,h:n.h*sc,scale:sc});}used.add(n.id);groups[n.id]=groups[native.id];
  }
  if(graph.nodes.some(n=>n.role!=='background'&&!used.has(n.id)))continue;
  const allowedOverlaps=graph.edges.filter(e=>e.accepted).map(e=>e.ids);for(const n of graph.nodes.filter(n=>n.materialAttachTo!==undefined))allowedOverlaps.push([n.id,n.materialAttachTo]);
  plans.push({engine:'relationships-v1',planner:'photo-scene-v1',candidate:'photo-scene-'+variant,layoutLabel:'사진 원본·겹침 유지 · 문구 재배치',mode:wide?'landscape':'portrait',width,height,roles,placements,backgrounds:graph.backgrounds,layoutGroups:groups,fontFloorById:floors,typographyMinimums:minimums,semanticUnits:placements.map(p=>({id:groups[p.id],role:p.role,band:'scene',ids:[p.id]})),graphBasis:Object.fromEntries(graph.nodes.map(n=>[n.id,n.basis])),allowedOverlaps,paintOrder:elements.map(n=>n.id),safeZone:{x:m,y:m,w:width-m*2,h:height-m*2},margin:m,gap,quality:{outside:[],overlaps:[]},warnings:['사진과 원래 겹친 글자를 유지했습니다. 상품 중요 부위 가림과 배경 연결은 직접 확인하세요.'],sourceGraph:graph,materialMode:true,relations:wide?[{type:'source-title-rows',rows:titles.map(n=>[n.id])}]:[],protectedRegions:wide?[{id:photo.id,...frame,except:native.filter(n=>!titles.includes(n)).map(n=>n.id)}]:[]});
 }for(const plan of plans)plan.backgroundTreatment={strategy:'separate-flat-native-base-and-original-photo',status:'review',reason:'단색 배경판과 원본 사진을 분리 배치했습니다. 사진 바깥 배경의 자연 연장은 검증되지 않아 검토가 필요합니다.'};return{plans,failures:[]};
}
